SELECT json_build_object('assessments',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY t."complianceAssessmentId")::text) FROM "complianceAssessments" t),'checks',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY t."complianceEvidenceCheckId")::text) FROM "complianceEvidenceChecks" t),'surveys',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY t."surveyId")::text) FROM surveys t),'existingStandards',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY t."standardId")::text) FROM standards t WHERE lower("standardNumber") NOT IN ('24','25')));
